GRANT EXECUTE ON FUNCTION public.claim_listing_write_reconcile_v1(),public.record_listing_write_reconcile_v1(uuid,uuid,text,uuid,text,text,integer) TO service_role;
SET LOCAL ROLE service_role; SELECT current_user='service_role' AS actual, public.claim_listing_write_reconcile_v1() AS job
\gset rw_
RESET ROLE;
INSERT INTO final_test.ctx VALUES('recon',:'rw_job'::jsonb);
SELECT reconcile_test.call_sql() AS call
\gset rw_
SET LOCAL ROLE service_role;
:rw_call
\gset rw_result_
RESET ROLE;
SELECT final_test.check('actual_service_role_can_claim_and_record',(:'rw_actual')::boolean IS TRUE AND (:'rw_result_record_listing_write_reconcile_v1')::jsonb->>'state'='settled');
ROLLBACK TO role;
